 * Value construction and printing. A value is one of a number, text, a
 * boolean, or an error, as described in the task specification.
 */

export function numVal(value) {
  return { type: 'number', value }
}

export function textVal(value) {
  return { type: 'text', value }
}

export function boolVal(value) {
  return { type: 'bool', value }
}

export function errVal(token) {
  return { type: 'error', value: token }
}

const ERROR_TOKENS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])

export function isErrorToken(text) {
  return ERROR_TOKENS.has(text)
}

/**
 * Round a finite number to ten significant digits and format it the way
 * JavaScript would print the rounded number.
 */
export function formatNumber(x) {
  if (x === 0) return '0'
  const rounded = Number(x.toPrecision(10))
  return String(rounded)
}

export function formatValue(value) {
  switch (value.type) {
    case 'number':
      return formatNumber(value.value)
    case 'bool':
      return value.value ? 'TRUE' : 'FALSE'
    case 'error':
      return value.value
    case 'text':
      return value.value
    default:
      throw new Error(`unknown value type: ${value.type}`)
  }
}
"}

