{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260921T233347Z/cell-pjvIjn/src/address.js","content":"/**
 * Cell address parsing, ordering, and range expansion. An address is one or
 * two letters naming a column and one to three digits naming a row of at
 * least 1.
 */

const ADDRESS_RE = /^([A-Z]{1,2})([0-9]{1,3})$/

/**
 * Convert column letters (already upper-cased) to their 1-based ascending
 * index: A=1, ..., Z=26, AA=27, ..., ZZ=702.
 */
export function colToIndex(letters) {
  let idx = 0
  for (const ch of letters) {
    idx = idx * 26 + (ch.charCodeAt(0) - 64)
  }
  return idx
}

/** Convert a 1-based column index back to its letters. */
export function indexToCol(n) {
  let s = ''
  while (n > 0) {
    const rem = (n - 1) % 26
    s = String.fromCharCode(65 + rem) + s
    n = Math.floor((n - 1) / 26)
  }
  return s
}

/**
 * Parse text (already upper-cased) as a cell address. Returns null when the
 * text is not shaped like an address or names row 0; the caller decides
 * whether that means an invalid declaration or an out-of-range reference.
 */
export function parseAddress(text) {
  const m = ADDRESS_RE.exec(text)
  if (!m) return null
  const row = parseInt(m[2], 10)
  if (row < 1) return null
  return { col: m[1], row, key: `${m[1]}${row}` }
}

/** Sort comparator for addresses in ascending column then row order. */
export function compareAddresses(a, b) {
  const ca = colToIndex(a.col)
  const cb = colToIndex(b.col)
  if (ca !== cb) return ca - cb
  return a.row - b.row
}

/**
 * Expand a range spanning two corner addresses into every cell it covers,
 * in ascending column then row order, regardless of which corner was
 * written first.
 */
export function expandRange(a, b) {
  const colA = colToIndex(a.col)
  const colB = colToIndex(b.col)
  const minCol = Math.min(colA, colB)
  const maxCol = Math.max(colA, colB)
  const minRow = Math.min(a.row, b.row)
  const maxRow = Math.max(a.row, b.row)
  const cells = []
  for (let c = minCol; c <= maxCol; c++) {
    const letters = indexToCol(c)
    for (let r = minRow; r <= maxRow; r++) {
      cells.push({ col: letters, row: r, key: `${letters}${r}` })
    }
  }
  return cells
}
"}

