{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260921T233347Z/cell-pjvIjn/src/lexer.js","content":"/**
 * Tokenizer for formula bodies (the text after the leading `=`).
 */

export class LexError extends Error {}

const TWO_CHAR_OPS = ['<=', '>=', '<>']
const ONE_CHAR_OPS = ['^', '*', '/', '+', '-', '=', '<', '>']

export function tokenize(text) {
  const tokens = []
  let i = 0
  const n = text.length
  while (i < n) {
    const ch = text[i]
    if (ch === ' ' || ch === '\t') {
      i++
      continue
    }
    if (ch === '(') {
      tokens.push({ type: 'lparen' })
      i++
      continue
    }
    if (ch === ')') {
      tokens.push({ type: 'rparen' })
      i++
      continue
    }
    if (ch === ',') {
      tokens.push({ type: 'comma' })
      i++
      continue
    }
    if (ch === ':') {
      tokens.push({ type: 'colon' })
      i++
      continue
    }
    if (/[0-9]/.test(ch)) {
      let j = i + 1
      while (j < n && /[0-9]/.test(text[j])) j++
      if (text[j] === '.' && /[0-9]/.test(text[j + 1] || '')) {
        j++
        while (j < n && /[0-9]/.test(text[j])) j++
      }
      tokens.push({ type: 'num', value: text.slice(i, j) })
      i = j
      continue
    }
    if (/[A-Za-z]/.test(ch)) {
      let j = i + 1
      while (j < n && /[A-Za-z0-9]/.test(text[j])) j++
      tokens.push({ type: 'ident', value: text.slice(i, j).toUpperCase() })
      i = j
      continue
    }
    const two = text.slice(i, i + 2)
    if (TWO_CHAR_OPS.includes(two)) {
      tokens.push({ type: 'op', value: two })
      i += 2
      continue
    }
    if (ONE_CHAR_OPS.includes(ch)) {
      tokens.push({ type: 'op', value: ch })
      i++
      continue
    }
    throw new LexError(`unexpected character ${ch}`)
  }
  return tokens
}
"}

