 * Recursive-descent parser for formula bodies. Produces an AST or throws
 * ParseError when the grammar does not accept the token stream. Ranges
 * (`A1:B3`) parse anywhere a primary expression is allowed; whether a given
 * range is directly a function argument is a semantic question the
 * evaluator answers, not a grammar question.
 */

import { LexError, tokenize } from './lexer.js'

export class ParseError extends Error {}

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])
const CALL_NAMES = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF'])

class TokenStream {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }
  peek() {
    return this.tokens[this.pos]
  }
  next() {
    return this.tokens[this.pos++]
  }
  atEnd() {
    return this.pos >= this.tokens.length
  }
}

export function parseFormula(text) {
  let tokens
  try {
    tokens = tokenize(text)
  } catch (e) {
    if (e instanceof LexError) throw new ParseError(e.message)
    throw e
  }
  const ts = new TokenStream(tokens)
  const node = parseComparison(ts)
  if (!ts.atEnd()) throw new ParseError('unexpected trailing input')
  return node
}

function parseComparison(ts) {
  let left = parseAdditive(ts)
  for (;;) {
    const tok = ts.peek()
    if (tok && tok.type === 'op' && COMPARISON_OPS.has(tok.value)) {
      ts.next()
      const right = parseAdditive(ts)
      left = { type: 'binary', op: tok.value, left, right }
    } else break
  }
  return left
}

function parseAdditive(ts) {
  let left = parseMultiplicative(ts)
  for (;;) {
    const tok = ts.peek()
    if (tok && tok.type === 'op' && (tok.value === '+' || tok.value === '-')) {
      ts.next()
      const right = parseMultiplicative(ts)
      left = { type: 'binary', op: tok.value, left, right }
    } else break
  }
  return left
}

function parseMultiplicative(ts) {
  let left = parsePower(ts)
  for (;;) {
    const tok = ts.peek()
    if (tok && tok.type === 'op' && (tok.value === '*' || tok.value === '/')) {
      ts.next()
      const right = parsePower(ts)
      left = { type: 'binary', op: tok.value, left, right }
    } else break
  }
  return left
}

function parsePower(ts) {
  const left = parseUnary(ts)
  const tok = ts.peek()
  if (tok && tok.type === 'op' && tok.value === '^') {
    ts.next()
    const right = parsePower(ts)
    return { type: 'binary', op: '^', left, right }
  }
  return left
}

function parseUnary(ts) {
  const tok = ts.peek()
  if (tok && tok.type === 'op' && (tok.value === '+' || tok.value === '-')) {
    ts.next()
    const operand = parseUnary(ts)
    return { type: 'unary', op: tok.value, operand }
  }
  return parsePrimary(ts)
}

function parsePrimary(ts) {
  const tok = ts.peek()
  if (!tok) throw new ParseError('unexpected end of formula')

  if (tok.type === 'num') {
    ts.next()
    return { type: 'num', value: parseFloat(tok.value) }
  }

  if (tok.type === 'lparen') {
    ts.next()
    const inner = parseComparison(ts)
    const close = ts.next()
    if (!close || close.type !== 'rparen') throw new ParseError('expected )')
    return inner
  }

  if (tok.type === 'ident') {
    ts.next()
    const name = tok.value
    const after = ts.peek()
