 * Parse raw sheet text into cell declarations, in source line order.
 */

import { parseAddress } from './address.js'

export class SheetError extends Error {
  constructor(message) {
    super(message)
  }
}

/**
 * Parse `input` into a Map from canonical address key to
 * `{ address, content, line }`. Throws SheetError with a fully formed
 * message (missing only the `error: ` prefix) on the first invalid or
 * duplicate address.
 */
export function parseSheet(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()
  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const rawLine = lines[i]
    const stripped = rawLine.replace(/^[ \t]+/, '')
    if (stripped === '' || stripped.startsWith('#')) continue

    const m = /[ \t]/.exec(stripped)
    let addrText, content
    if (!m) {
      addrText = stripped
      content = ''
    } else {
      addrText = stripped.slice(0, m.index)
      const rest = stripped.slice(m.index)
      const skip = /^[ \t]+/.exec(rest)
      content = rest.slice(skip[0].length)
    }

    const upperAddr = addrText.toUpperCase()
    const parsed = parseAddress(upperAddr)
    if (!parsed) {
      throw new SheetError(`line ${lineNo}: invalid cell address ${upperAddr}`)
    }
    if (cells.has(parsed.key)) {
      throw new SheetError(`line ${lineNo}: cell ${upperAddr} is declared twice`)
    }
    cells.set(parsed.key, { address: parsed, content, line: lineNo })
  }
  return cells
}
