    cmp = typeRank(l.type) - typeRank(r.type)
  } else if (l.type === 'number' || l.type === 'text') {
    cmp = l.value < r.value ? -1 : l.value > r.value ? 1 : 0
  } else {
    const a = l.value ? 1 : 0
    const b = r.value ? 1 : 0
    cmp = a - b
