  switch (op) {
    case '=':
      result = cmp === 0
      break
    case '<>':
      result = cmp !== 0
      break
    case '<':
      result = cmp < 0
      break
    case '<=':
      result = cmp <= 0
      break
    case '>':
      result = cmp > 0
      break
    case '>=':
      result = cmp >= 0
