    const values = collectArgValues(argNodes, ctx)
    return computeAggregate(upper, values)
  }
  if (upper === 'ABS') {
    if (argNodes.length !== 1) return errVal('#ERR!')
    const v = evalExpr(argNodes[0], ctx)
    if (v.type === 'error') return v
    const r = readNumber(v)
    if (!r.ok) return r.err
    return finiteOrDivErr(Math.abs(r.num))
  }
  if (upper === 'IF') {
    if (argNodes.length !== 3) return errVal('#ERR!')
    const cond = evalExpr(argNodes[0], ctx)
    if (cond.type === 'error') return cond
    let truthy
    if (cond.type === 'bool') truthy = cond.value
    else if (cond.type === 'number') truthy = cond.value !== 0
    else return errVal('#VALUE!')
    return evalExpr(truthy ? argNodes[1] : argNodes[2], ctx)
