    case 'AVG':
      return finiteOrDivErr(nums.reduce((a, b) => a + b, 0) / nums.length)
    case 'MIN':
      return finiteOrDivErr(Math.min(...nums))
    case 'MAX':
      return finiteOrDivErr(Math.max(...nums))
    default:
      throw new Error(`unknown aggregate: ${kind}`)
  }
}

